CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE order_status AS ENUM ('PENDIENTE','EN_PRODUCCION','IMPRESO','LISTO','ENTREGADO','CANCELADO');
CREATE TYPE extra_type AS ENUM ('TELA_TRASLUCIDA','MONO','PLANTA_PEQUENA','HOJA_OPALINA','FLORES','AROMA','LIBRO_MINIATURA','CENTRO_MESA','OTRO');
CREATE TYPE asset_purpose AS ENUM ('PRODUCT_REFERENCE','COLLECTION_REFERENCE','SYSTEM_CUSTOMIZATION','ORDER_CUSTOMIZATION','LEGACY');
CREATE TABLE admin_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), username text NOT NULL UNIQUE, password_hash text NOT NULL, must_change_password boolean NOT NULL DEFAULT true, failed_login_attempts integer NOT NULL DEFAULT 0 CHECK(failed_login_attempts>=0), locked_until timestamptz(3), created_at timestamptz(3) NOT NULL DEFAULT now());
CREATE TABLE categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, base_prep_time_minutes integer NOT NULL DEFAULT 0 CHECK(base_prep_time_minutes>=0), is_active boolean NOT NULL DEFAULT true);
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category_id uuid NOT NULL REFERENCES categories(id) ON DELETE RESTRICT, name text NOT NULL, description text NOT NULL DEFAULT '', base_price numeric(10,2) NOT NULL CHECK(base_price>=0), prep_time_minutes integer NOT NULL CHECK(prep_time_minutes>=0), stock_available integer NOT NULL DEFAULT 0 CHECK(stock_available>=0), is_customizable boolean NOT NULL DEFAULT false, is_active boolean NOT NULL DEFAULT true);
CREATE TABLE product_reference_images (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE, image_url text NOT NULL, alt_text text, sort_order integer NOT NULL DEFAULT 0, UNIQUE(product_id,sort_order));
CREATE INDEX products_category_active_idx ON products(category_id,is_active);
CREATE TABLE customization_extras (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), extra_type extra_type NOT NULL, name text NOT NULL, additional_cost numeric(10,2) NOT NULL CHECK(additional_cost>=0), additional_prep_minutes integer NOT NULL DEFAULT 0 CHECK(additional_prep_minutes>=0), preview_image_url text, is_available boolean NOT NULL DEFAULT true);
CREATE INDEX customization_extras_available_type_idx ON customization_extras(is_available,extra_type);
CREATE TABLE typography_fonts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), font_family_name text NOT NULL UNIQUE, google_font_url text NOT NULL, is_active boolean NOT NULL DEFAULT true);
CREATE TABLE design_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, event_category text NOT NULL, template_image_url text NOT NULL, print_width_mm numeric(8,2) NOT NULL CHECK(print_width_mm>0), print_height_mm numeric(8,2) NOT NULL CHECK(print_height_mm>0), is_active boolean NOT NULL DEFAULT true);
CREATE INDEX design_templates_event_active_idx ON design_templates(event_category,is_active);
CREATE TABLE customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), first_name_encrypted text NOT NULL, last_name_encrypted text NOT NULL, phone_encrypted text NOT NULL, encryption_iv text NOT NULL, encryption_auth_tag text NOT NULL, created_at timestamptz(3) NOT NULL DEFAULT now());
CREATE TABLE orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ticket_code text NOT NULL UNIQUE, customer_id uuid NOT NULL REFERENCES customers(id) ON DELETE RESTRICT, status order_status NOT NULL DEFAULT 'PENDIENTE', total_amount numeric(10,2) NOT NULL CHECK(total_amount>=0), calculated_ready_date date NOT NULL, customer_requested_date date NOT NULL, created_at timestamptz(3) NOT NULL DEFAULT now());
CREATE INDEX orders_status_ready_idx ON orders(status,calculated_ready_date);
CREATE INDEX orders_requested_date_idx ON orders(customer_requested_date);
CREATE TABLE order_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES products(id) ON DELETE RESTRICT, quantity integer NOT NULL CHECK(quantity>0), unit_price_calculated numeric(10,2) NOT NULL CHECK(unit_price_calculated>=0), subtotal numeric(10,2) NOT NULL CHECK(subtotal>=0));
CREATE INDEX order_items_order_idx ON order_items(order_id);
CREATE TABLE order_item_customizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_item_id uuid NOT NULL REFERENCES order_items(id) ON DELETE CASCADE, extra_id uuid REFERENCES customization_extras(id) ON DELETE SET NULL, custom_text text, font_id uuid REFERENCES typography_fonts(id) ON DELETE SET NULL, template_id uuid REFERENCES design_templates(id) ON DELETE SET NULL, customer_photo_url text, generated_high_res_print_url text, print_width_mm numeric(8,2) CHECK(print_width_mm>0), print_height_mm numeric(8,2) CHECK(print_height_mm>0), is_printed boolean NOT NULL DEFAULT false);
CREATE INDEX order_customizations_print_idx ON order_item_customizations(is_printed,order_item_id);
CREATE TABLE workshop_config (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), daily_work_minutes integer NOT NULL DEFAULT 480 CHECK(daily_work_minutes>0), minimum_buffer_hours integer NOT NULL DEFAULT 24 CHECK(minimum_buffer_hours>=0), updated_at timestamptz(3) NOT NULL DEFAULT now());
CREATE TABLE workshop_holidays (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workshop_config_id uuid NOT NULL REFERENCES workshop_config(id) ON DELETE CASCADE, holiday_date date NOT NULL, label text, UNIQUE(workshop_config_id,holiday_date));
CREATE TABLE ticket_sequences (year integer PRIMARY KEY, last_number integer NOT NULL DEFAULT 0 CHECK(last_number>=0));
CREATE TABLE uploaded_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), purpose asset_purpose NOT NULL DEFAULT 'LEGACY', storage_key text NOT NULL UNIQUE, content_type text NOT NULL, size_bytes integer NOT NULL CHECK(size_bytes>0), width_pixels integer NOT NULL CHECK(width_pixels>0), height_pixels integer NOT NULL CHECK(height_pixels>0), encryption_iv text NOT NULL, encryption_auth_tag text NOT NULL, created_at timestamptz(3) NOT NULL DEFAULT now());
CREATE INDEX uploaded_assets_purpose_created_idx ON uploaded_assets(purpose,created_at);
